package reasongate

import (
	"encoding/json"
	"os"
	"testing"

	"github.com/websines/structor-harness/resolver"
)

// exhaustiveCorpus is the FULL evidence→state domain — every semantically-distinct
// input class (64), generated by engine/internal/resolver/exhaustivegen and
// Lean-certified in proofs/ForgeProofs/Exhaustive.lean (see the sibling
// internal/resolver/exhaustive_test.go for the Phase-1 machinery).
const exhaustiveCorpus = "../conformance/exhaustive/evidence_state.json"

// TestDatalogAgreesWithResolverExhaustive extends the 9-vector agreement
// (TestAgreesWithResolverOnVectors) to the ENTIRE finite evidence→state domain: the
// proof-carrying Datalog program (the canonical rule set) derives the identical state
// as the hand-coded resolver on ALL 64 classes. Combined with Phase 1's Lean decide
// (deriveObligationState ≡ the same corpus over the 64), this closes the triple —
// hand-coded Go ≡ Datalog ≡ Lean model agree over the whole finite domain, with the
// corpus as the shared pivot. The three encodings are ONE rule set, checked
// exhaustively rather than on 9 samples.
func TestDatalogAgreesWithResolverExhaustive(t *testing.T) {
	raw, err := os.ReadFile(exhaustiveCorpus)
	if err != nil {
		t.Fatalf("read exhaustive corpus: %v (regenerate: go run ./internal/resolver/exhaustivegen)", err)
	}
	var vs []vector
	if err := json.Unmarshal(raw, &vs); err != nil {
		t.Fatalf("unmarshal exhaustive corpus: %v", err)
	}
	if len(vs) != 64 {
		t.Fatalf("corpus has %d classes, want 64 — stale; regenerate with go run ./internal/resolver/exhaustivegen", len(vs))
	}
	for _, v := range vs {
		obl, evs, sups := v.build()
		datalog, proof := ResolveViaDatalog(obl, evs, sups)
		hand := resolver.ResolveObligation(obl, evs, sups).State
		if string(datalog) != string(hand) {
			t.Errorf("class %s (%s): datalog %q disagrees with hand-coded resolver %q\nproof:\n%s",
				v.ID, v.Name, datalog, hand, proofString(proof))
		}
		if string(datalog) != v.Expect {
			t.Errorf("class %s (%s): datalog %q disagrees with Lean-certified corpus %q",
				v.ID, v.Name, datalog, v.Expect)
		}
	}
}
